contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test function
    // params: minSum to initialize, depositAmt to deposit, collectAmt to attempt to collect
    function run(uint minSum, uint depositAmt, uint collectAmt) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmt)); require(depositAmt <= 1000000000000000000000000000000);
        require(address(this).balance >= depositAmt);

        // initialize C (before Initialized is set)
        c.SetMinSum(minSum); if (__ESBMC_reverted()) return;
        c.SetLogFile(address(this)); if (__ESBMC_reverted()) return;
        c.Initialized(); if (__ESBMC_reverted()) return;

        // make an initial deposit so balances[this] may be nonzero
        c.Deposit{value: depositAmt}(); if (__ESBMC_reverted()) return;

        // record balance before attempting Collect
        uint before_recorded = c.balances(address(this)); if (__ESBMC_reverted()) return;

        // attempt Collect and catch revert
        bool reverted;
        c.Collect(collectAmt); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint after_recorded = c.balances(address(this)); if (__ESBMC_reverted()) return;

        // General invariant: a Collect call cannot increase the recorded balance of the caller
        assert(after_recorded <= before_recorded);
    }

    receive() external payable { }
}

